class formasActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('formas', 'list');
  }
  
    public function verificaPrilegio($currentForm)
  { 
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 
  }
  public function verificaPrilegioCerrar($currentForm)
  { 
 	$usuarioLoguiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuarioLoguiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 	  
  }

  public function executeConsulta()
  { 
   
	$this->forma = new Forma();
    
  }
  
  public function executeList()
  { 
  	$c = new Criteria();
  	$c =  $this->getBasicCriteria($c);
  	$this->verificaPrilegio("forma/list");  	
  	$pager=new sfPropelPager('Forma',15);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();
	$this->pager=$pager;   
	$this->controlPaginacion = 1;
  }
  
  public function executeLockedPerm()
  {
  	$forma = FormaPeer::retrieveByPk($this->getRequestParameter('forma_id'));
    $forma->setIsPublic(!$forma->getIsPublic());
    $forma->save();
    $this->forma = $forma;
  }
  
  
  public function executeExcel()
  { 
    $this->setLayout(false);
  	$this->formas = FormaPeer::doSelect($this->getBasicCriteria(new Criteria()));
  }
  
  public function executeShow()
  {
    $this->forma = FormaPeer::retrieveByPk($this->getRequestParameter('forma_id'));
    $this->forward404Unless($this->forma);
  }

  public function executeCreate()
  {
    $this->forma = new Forma();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->forma = FormaPeer::retrieveByPk($this->getRequestParameter('forma_id'));
    $this->forward404Unless($this->forma);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('forma_id'))
    {
      $forma = new Forma();
    }
    else
    {
      $forma = FormaPeer::retrieveByPk($this->getRequestParameter('forma_id'));
      $this->forward404Unless($forma);
    }

    //$forma->setFormaId($this->getRequestParameter('forma_id'));
    $forma->setModuloId($this->getRequestParameter('modulo_id') ? $this->getRequestParameter('modulo_id') : null);
    $forma->setNombre($this->getRequestParameter('nombre'));
    $forma->setDescripcion($this->getRequestParameter('descripcion'));
    $forma->setRuta($this->getRequestParameter('ruta'));
	$forma->setIsPublic($this->getRequestParameter('is_public') ? true : false);
    $forma->save();

    return $this->redirect($this->getRequest()->getScriptName().'/formas/show?forma_id='.$forma->getFormaId());
  }

  public function executeDelete()
  {
    $forma = FormaPeer::retrieveByPk($this->getRequestParameter('forma_id'));

    $this->forward404Unless($forma);

    $forma->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/formas/list');
  }
  
  private function getBasicCriteria(Criteria $c)
  {
  	$this->parametros="a=1";
  	$usuariologuiado=$this->getUser()->getAttribute('usuario_id','', 'subscriber');
  	//*********************************************************************************************************
  	if($this->getRequestParameter('modulo_id')){
  		$c->add(FormaPeer::MODULO_ID,$this->getRequestParameter('modulo_id'));
  		$this->parametros.="&modulo_id=".$this->getRequestParameter('modulo_id');
  	}
  	
  	if($this->getRequestParameter('nombre')){
  		$c->add(FormaPeer::NOMBRE,'%'.$this->getRequestParameter('nombre').'%',Criteria::LIKE);
  		$this->parametros.="&nombre=".$this->getRequestParameter('nombre');
  	}
  	
  	if($this->getRequestParameter('descripcion')){
  		$c->add(FormaPeer::DESCRIPCION,'%'.$this->getRequestParameter('descripcion').'%',Criteria::LIKE);
  		//$c->add(FormaPeer::DESCRIPCION,$this->getRequestParameter('descripcion'));
  		$this->parametros.="&descripcion=".$this->getRequestParameter('descripcion');
  	}	
  	if($this->getRequestParameter('es_publico') == "1"){
  		$c->add(FormaPeer::IS_PUBLIC,true);
  		$this->parametros.="&es_publico=".$this->getRequestParameter('es_publico');
  	}elseif($this->getRequestParameter('es_publico') == "2"){
  		$c->add(FormaPeer::IS_PUBLIC,false);
  		$this->parametros.="&es_publico=".$this->getRequestParameter('es_publico');
  	}
  	
  	if($this->getRequestParameter('orden')){
  		$c->addDescendingOrderByColumn(FormaPeer::$this->getRequestParameter('orden'));
  		$this->parametros.="&orden=".$this->getRequestParameter('orden');
  	}else{
  		$c->addAscendingOrderByColumn(FormaPeer::DESCRIPCION);
  	}
  	 
  	if(!$this->getRequestParameter('panelControl')){
  		//$c->add(FormaPeer::MODULO_ID,11,Criteria::NOT_EQUAL);
  	}else{
  		$this->parametros.="&panelControl=".$this->getRequestParameter('panelControl');
  	}
  	
  	if(!$this->getUser()->checkPerm("VER_TODOS_PRIVILEGIOS", $usuariologuiado)){
  		$c->add(FormaPeer::IS_PUBLIC,true);
  	}
  	//**************************************************************************************************
  	return $c;
  }
}
